<?php
declare(strict_types=1);
namespace Tests\Feature;
use App\Models\ClubOrdinaryIncomeReceipt; use App\Services\Finance\ClubOrdinaryIncomeReceiptService; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str; use ReflectionClass; use Symfony\Component\Process\Process; use Tests\TestCase; use Throwable;

final class Milestone3iizzPostgresOrdinaryIncomeReceiptConcurrencyTest extends TestCase
{
    public function test_concurrent_replays_tenant_identity_and_atomicity_hold_on_postgres(): void
    {
        $this->assertSame('1', env('RUN_3IIZZ_POSTGRES_CONCURRENCY')); $this->assertSame('pgsql', DB::connection()->getDriverName()); $this->assertSame('lcb_3iizz_ordinary_income_receipt_concurrency_test', DB::connection()->getDatabaseName()); $this->assertNotSame('lc_beenachi_connect_reconstructed_20260727', DB::connection()->getDatabaseName());
        $exact = $this->fixture('PGX'); $key = (string) Str::uuid(); $payload = $this->payload($exact, $key, 100); $results = $this->race($exact, $payload, $payload); $this->assertSame(['success', 'success'], collect($results)->pluck('status')->sort()->values()->all()); $this->assertSame($results[0]['receipt'], $results[1]['receipt']); $this->assertEffect($exact, 1, 1, 2); $receipt = ClubOrdinaryIncomeReceipt::where('club_id', $exact['club']->id)->firstOrFail(); $journal = DB::table('club_journal_entries')->where('id', $receipt->journal_entry_id)->first(); $lines = DB::table('club_journal_lines')->where('journal_entry_id', $receipt->journal_entry_id)->orderBy('line_number')->get(); $this->assertSame('INR', $journal->currency); $this->assertSame([$exact['bank']->id, $exact['income']->id], $lines->pluck('ledger_account_id')->all()); $this->assertSame(['debit', 'credit'], $lines->pluck('direction')->all()); $this->assertSame([100, 100], $lines->pluck('amount_paise')->all()); $this->assertSame(['GENERAL_CLUB_FUND'], $lines->pluck('fund_code')->unique()->values()->all());
        $changed = $this->fixture('PGC'); $key = (string) Str::uuid(); $results = $this->race($changed, $this->payload($changed, $key, 101), $this->payload($changed, $key, 202)); $this->assertSame(['conflict', 'success'], collect($results)->pluck('status')->sort()->values()->all()); $this->assertEffect($changed, 1, 1, 2);
        $a = $this->fixture('PGA'); $b = $this->fixture('PGB'); $tenantKey = (string) Str::uuid(); app(ClubOrdinaryIncomeReceiptService::class)->record($a['club'], $a['actor'], $this->payload($a, $tenantKey, 303)); app(ClubOrdinaryIncomeReceiptService::class)->record($b['club'], $b['actor'], $this->payload($b, $tenantKey, 404)); $this->assertSame(1, ClubOrdinaryIncomeReceipt::where('club_id', $a['club']->id)->where('idempotency_key', $tenantKey)->count()); $this->assertSame(1, ClubOrdinaryIncomeReceipt::where('club_id', $b['club']->id)->where('idempotency_key', $tenantKey)->count()); foreach ([['receiving_account' => $b['bank']->public_id], ['income_account' => $b['income']->public_id]] as $change) { try { app(ClubOrdinaryIncomeReceiptService::class)->record($a['club'], $a['actor'], [...$this->payload($a, (string) Str::uuid(), 405), ...$change]); $this->fail('Cross-tenant account use must fail.'); } catch (\App\Services\Finance\Exceptions\ClubOrdinaryIncomeReceiptException) {} } $this->assertSame(1, ClubOrdinaryIncomeReceipt::where('club_id', $a['club']->id)->count()); $this->assertSame(1, DB::table('club_journal_entries')->where('club_id', $a['club']->id)->where('source_type', ClubOrdinaryIncomeReceiptService::SOURCE_TYPE)->count());
        $atomic = $this->fixture('PGF'); DB::unprepared("CREATE FUNCTION reject_3iizz_receipt() RETURNS trigger LANGUAGE plpgsql AS \$\$ BEGIN IF NEW.source_type = 'club_ordinary_income_receipt' THEN RAISE EXCEPTION 'controlled ordinary income failure'; END IF; RETURN NEW; END \$\$"); DB::unprepared('CREATE TRIGGER reject_3iizz_receipt BEFORE INSERT ON club_journal_entries FOR EACH ROW EXECUTE FUNCTION reject_3iizz_receipt()'); try { app(ClubOrdinaryIncomeReceiptService::class)->record($atomic['club'], $atomic['actor'], $this->payload($atomic, (string) Str::uuid(), 505)); $this->fail('Controlled PostgreSQL journal failure must propagate.'); } catch (Throwable) { $this->assertSame(0, ClubOrdinaryIncomeReceipt::where('club_id', $atomic['club']->id)->count()); } $this->assertSame(0, DB::table('club_journal_entries')->where('club_id', $atomic['club']->id)->where('source_type', ClubOrdinaryIncomeReceiptService::SOURCE_TYPE)->count()); DB::unprepared('DROP TRIGGER reject_3iizz_receipt ON club_journal_entries'); DB::unprepared('DROP FUNCTION reject_3iizz_receipt()');
    }
    private function fixture(string $suffix): array { $reflection = new ReflectionClass(Milestone3iizzOrdinaryIncomeReceiptTest::class); $instance = $reflection->newInstanceWithoutConstructor(); return $reflection->getMethod('fixture')->invoke($instance, $suffix); }
    private function payload(array $f, string $key, int $amount): array { return ['subtype' => 'interest', 'accounting_date' => '2027-08-10', 'receiving_account' => $f['bank']->public_id, 'income_account' => $f['income']->public_id, 'fund' => 'GENERAL_CLUB_FUND', 'amount_paise' => $amount, 'description' => 'Concurrent bank interest', 'payer_name' => null, 'external_reference' => 'PG', 'event_label' => null, 'idempotency_key' => $key]; }
    private function race(array $f, array $first, array $second): array { $barrier = sys_get_temp_dir().DIRECTORY_SEPARATOR.'3iizz-receipt-'.Str::lower(Str::random(10)); mkdir($barrier, 0700, true); $processes = []; foreach ([$first, $second] as $i => $payload) { $request = $barrier.DIRECTORY_SEPARATOR."request.{$i}.json"; file_put_contents($request, json_encode(['club' => $f['club']->id, 'actor' => $f['actor']->id, 'payload' => $payload], JSON_THROW_ON_ERROR)); $processes[$i] = new Process([PHP_BINARY, base_path('tests/Support/Milestone3iizzOrdinaryIncomeReceiptWorker.php'), $request, $barrier, (string) $i], base_path(), timeout: 40); $processes[$i]->start(); } $deadline = microtime(true) + 20; while (! file_exists($barrier.DIRECTORY_SEPARATOR.'ready.0') || ! file_exists($barrier.DIRECTORY_SEPARATOR.'ready.1')) { if (microtime(true) >= $deadline) throw new \RuntimeException('Barrier timeout.'); usleep(10000); } file_put_contents($barrier.DIRECTORY_SEPARATOR.'go', '1'); foreach ($processes as $process) { $process->wait(); $this->assertTrue($process->isSuccessful(), $process->getErrorOutput().$process->getOutput()); } return array_map(fn ($i) => json_decode((string) file_get_contents($barrier.DIRECTORY_SEPARATOR."result.{$i}.json"), true, flags: JSON_THROW_ON_ERROR), [0, 1]); }
    private function assertEffect(array $f, int $receipts, int $journals, int $lines): void { $this->assertSame($receipts, ClubOrdinaryIncomeReceipt::where('club_id', $f['club']->id)->count()); $ids = DB::table('club_journal_entries')->where('club_id', $f['club']->id)->where('source_type', ClubOrdinaryIncomeReceiptService::SOURCE_TYPE)->pluck('id'); $this->assertCount($journals, $ids); $this->assertSame($lines, DB::table('club_journal_lines')->whereIn('journal_entry_id', $ids)->count()); }
}
